package org.eclipse.rdf4j.common.iteration;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.FutureTask;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.Test;

class DelayedIterationLifecycleTest {

	@Test
	void closingDuringCreationClosesTheReturnedIteration() {
		var closes = new AtomicInteger();
		var delegate = new CloseableIteratorIteration<>(List.of(1).iterator()) {
			@Override
			protected void handleClose() {
				closes.incrementAndGet();
			}
		};
		try (var delayed = new DelayedIteration<Integer>() {
			@Override
			protected CloseableIteration<? extends Integer> createIteration() {
				close();
				return delegate;
			}
		}) {
			boolean emitted = delayed.hasNext();
			assertEquals(1, closes.get());
			assertFalse(emitted);
		}
		assertEquals(1, closes.get());
	}

	@Test
	void closeCanReturnWhileSynchronizedCreationIsStillRunning() throws Exception {
		var opening = new CountDownLatch(1);
		var finishOpening = new CountDownLatch(1);
		try (var delayed = new DelayedIteration<Integer>() {
			@Override
			protected synchronized CloseableIteration<? extends Integer> createIteration() {
				opening.countDown();
				try {
					finishOpening.await();
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new AssertionError(e);
				}
				return new CloseableIteratorIteration<>(List.of(1).iterator());
			}
		}) {
			var firstPull = new FutureTask<>(delayed::hasNext);
			Thread.ofPlatform().daemon().start(firstPull);
			try {
				assertTrue(opening.await(5, TimeUnit.SECONDS));
				var closing = new FutureTask<>(delayed::close, null);
				Thread.ofPlatform().daemon().start(closing);
				assertDoesNotThrow(() -> closing.get(5, TimeUnit.SECONDS), "close must finish without the delegate");
			} finally {
				finishOpening.countDown();
			}
			assertFalse(firstPull.get(5, TimeUnit.SECONDS));
		}
	}
}
